func (e *encoder) encObject(v check.Object) {
	switch x := v.(type) {
	case nil:
		e.uint(0)
	case *check.Builtin:
		e.uint(1)
		e.encPtrBuiltin(x)
	case *check.Const:
		e.uint(2)
		e.encPtrConst(x)
	case *check.Context:
		e.uint(3)
		e.encPtrContext(x)
	case *check.Field:
		e.uint(4)
		e.encPtrField(x)
	case *check.Func:
		e.uint(5)
		e.encPtrFunc(x)
	case *check.Law:
		e.uint(6)
		e.encPtrLaw(x)
	case *check.Method:
		e.uint(7)
		e.encPtrMethod(x)
	case *check.PkgName:
		e.uint(8)
		e.encPtrPkgName(x)
	case *check.TypeName:
		e.uint(9)
		e.encPtrTypeName(x)
	case *check.TypeParam:
		e.uint(10)
		e.encPtrTypeParam(x)
	case *check.Var:
		e.uint(11)
		e.encPtrVar(x)
	case *check.Codec_capBinding:
		e.uint(12)
		e.encPtrcapBinding(x)
	case *check.Codec_explicitArgs:
		e.uint(13)
		e.encPtrexplicitArgs(x)
	default:
		if syntax.IsObject(x) {
			e.uint(14)
			e.node(x)
			return
		}
		if i, ok := e.external(x); ok {
			e.uint(15)
			e.uint(i)
			return
		}
		e.failf("no codec for a %T in check.Object", x)
	}
}

