func (e *encoder) encSnapshotSource(v check.SnapshotSource) {
	switch x := v.(type) {
	case nil:
		e.uint(0)
	default:
		if syntax.IsObject(x) {
			e.uint(1)
			e.node(x)
			return
		}
		if i, ok := e.external(x); ok {
			e.uint(2)
			e.uint(i)
			return
		}
		e.failf("no codec for a %T in check.SnapshotSource", x)
	}
}

